-- ============================================================
-- 教会每日读经计划：旧约 1 章 + 新约 1 章（按书卷顺序按日推进）
-- 锚点：2026-11-17 = 耶利米哀歌 5 章 + 以弗所书 5 章（教会确认）
-- 范围：2026-11-17 ～ 2027-11-16，共 365 天
-- 译本：新译本（仅录入经文出处，不录入经文全文；全文版权确认后再由管理员补入 content）
-- 用法：在 Supabase 后台 SQL Editor 整段粘贴运行一次即可（可重复运行，不会重复插入）
-- 作用：删除示例用的『试点读经计划』及其示例经文，写入正式计划与 365 天经文出处
-- ============================================================
begin;

-- 清理示例计划（其示例经文会随计划级联删除）与同名正式计划（保证可重复运行）
delete from public.reading_plans where title in ('试点读经计划', '每日读经计划');

insert into public.reading_plans (title, description, starts_on)
values ('每日读经计划', '每天旧约1章、新约1章，按书卷顺序推进。圣经译本：新译本。起始锚点：2026-11-17 耶利米哀歌5章、以弗所书5章。', date '2026-11-17');

